 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find a repeated row of palette colors (the legend), allowing surrounding zeros.
    legend_rows = None
    for r in range(h - 1):
        if grid[r] == grid[r + 1] and any(grid[r]):
            end = r + 2
            while end < h and grid[end] == grid[r]:
                end += 1
            vals = [v for v in grid[r] if v]
            if len(vals) >= 2:
                legend_rows = (r, end, vals)
                break
    if legend_rows is None:
        raise ValueError('palette legend not found')
    r0, r1, colors = legend_rows
    # Keep each palette color once, in its left-to-right order.
    palette = []
    for c in colors:
        if c not in palette:
            palette.append(c)
    # The single-color motif is color 1, excluding the legend.
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] == 1 and not (r0 <= r < r1)]
    if not pts:
        raise ValueError('motif not found')
    top = min(r for r, c in pts)
    left = min(c for r, c in pts)
    bottom = max(r for r, c in pts)
    shape = [(r - top, c - left) for r, c in pts]
    sh = bottom - top + 1
    try:
        original_index = palette.index(1)
    except ValueError:
        raise ValueError('original color absent from palette')
    out = [[0] * w for _ in range(h)]
    # Stack motif copies contiguously while keeping the original copy's location.
    start = top - original_index * sh
    for i, color in enumerate(palette):
        base = start + i * sh
        for dr, dc in shape:
            rr, cc = base + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
